{"cards": [{"node_code": "N_39bf1287a7774656", "definition": "研究以全身性自身免疫反应为特征、累及多系统结缔组织的疾病，涵盖系统性红斑狼疮、系统性硬化症、多发性肌炎等。", "boundary": "本节点聚焦于弥漫性结缔组织病的病理机制、临床表现、诊断标准及内科治疗。收录SLE、硬皮病、混合性结缔组织病等疾病的诊疗。不涵盖局限于单一关节的炎性关节病（归脊柱关节病与骨关节病），也不涵盖以血管壁炎症为主要表现的血管炎（归血管炎与免疫检测）。", "includes": ["系统性红斑狼疮（SLE）的诊疗", "系统性硬化症（硬皮病）的诊疗", "多发性肌炎/皮肌炎及混合性结缔组织病"], "excludes": ["局限于脊柱或外周关节的炎性关节病", "以血管壁炎症为主要表现的血管炎"], "sibling_distinctions": [{"other_code": "N_5bfdd76e4cfdb59d", "rule": "本节点聚焦全身性多系统受累的结缔组织病，兄弟节点聚焦以脊柱或外周关节为主要受累部位的炎性关节病。"}, {"other_code": "N_d454eb9e18e96df5", "rule": "本节点聚焦结缔组织本身的免疫异常，兄弟节点聚焦血管壁炎症及相关的免疫学检测技术。"}], "cross_boundary_rule": "涉及多系统结缔组织受累的自身免疫病挂载至本节点；涉及特定关节结构病变挂载至脊柱关节病与骨关节病；涉及血管特异性炎症挂载至血管炎与免疫检测。"}, {"node_code": "N_5bfdd76e4cfdb59d", "definition": "研究以脊柱和外周关节慢性炎症为主要表现的疾病，涵盖强直性脊柱炎、反应性关节炎及骨关节炎等。", "boundary": "本节点聚焦于脊柱关节病（如强直性脊柱炎、银屑病关节炎）及退行性骨关节病的病理、诊断与治疗。收录炎性腰背痛、关节畸形评估及非手术干预。不涵盖全身性多系统结缔组织病（归弥漫性结缔组织病），也不涵盖关节置换或创伤修复等外科操作（归骨科学）。", "includes": ["强直性脊柱炎及脊柱关节病诊疗", "反应性关节炎与银屑病关节炎", "骨关节炎的保守治疗与评估"], "excludes": ["全身性多系统受累的结缔组织病", "关节置换、韧带重建等外科手术操作"], "sibling_distinctions": [{"other_code": "N_39bf1287a7774656", "rule": "本节点聚焦以关节/脊柱结构病变为主的疾病，兄弟节点聚焦以全身多系统结缔组织受累为主的疾病。"}, {"other_code": "N_bbfc534d16af8e07", "rule": "本节点侧重疾病分类与病理特征，兄弟节点侧重具体的药物治疗方案、生物制剂应用及康复策略。"}], "cross_boundary_rule": "涉及脊柱或外周关节的炎性/退行性病变挂载至本节点；涉及全身多系统结缔组织病挂载至弥漫性结缔组织病；涉及具体药物或康复方案挂载至风湿病治疗。"}, {"node_code": "N_d454eb9e18e96df5", "definition": "研究以血管壁炎症为病理基础的疾病及风湿免疫性疾病的实验室诊断技术，涵盖大/小血管炎及自身抗体检测。", "boundary": "本节点聚焦于血管炎（如巨细胞动脉炎、ANCA相关血管炎）的诊疗及风湿病相关的免疫学检测（如ANA、RF、抗CCP抗体）。收录血管炎的临床分型、免疫指标解读及诊断流程。不涵盖结缔组织病本身的全身性表现（归弥漫性结缔组织病），也不涵盖血管炎的具体药物治疗方案（归风湿病治疗）。", "includes": ["大血管炎与小血管炎的诊疗", "风湿病相关自身抗体及免疫指标检测", "血管炎与结缔组织病的鉴别诊断"], "excludes": ["结缔组织病本身的全身性多系统表现", "血管炎或风湿病的具体药物治疗方案"], "sibling_distinctions": [{"other_code": "N_39bf1287a7774656", "rule": "本节点聚焦血管壁炎症及检测技术，兄弟节点聚焦结缔组织本身的全身性免疫异常。"}, {"other_code": "N_bbfc534d16af8e07", "rule": "本节点侧重诊断与检测，兄弟节点侧重治疗干预与药物管理。"}], "cross_boundary_rule": "涉及血管壁特异性炎症或免疫检测技术挂载至本节点；涉及结缔组织全身性病变挂载至弥漫性结缔组织病；涉及具体治疗药物挂载至风湿病治疗。"}]}
